use super::*;
use rvn_parser::{enum_asset::{EnumAsset,EnumAssetId,EnumMemberId,EnumCommand},enum_asset_json::EnumIndexInput};
const A:&str="329f41eae6ba4b4bb71dfaf60fb50001";const M:&str="229f41eae6ba4b4bb71dfaf60fb50001";
fn asset()->EnumAsset{EnumAsset::new(EnumAssetId::parse(A).unwrap(),"Alpha".into()).unwrap().prepare(EnumCommand::Add{member:EnumMemberId::parse(M).unwrap(),display_name:"First".into(),description:String::new()}).unwrap().after().clone()}
fn resources(asset:&EnumAsset)->EnumAssets1025{let rows=[(A,Some("Alpha.rvnenum"))];EnumAssets1025::admit(EnumIndexInput::Table(&rows),&[("Alpha.rvnenum".into(),asset.encode().unwrap().into_bytes())],true).unwrap()}
fn program()->rvn_parser::ParsedProgram{rvn_parser::parse_program(&format!("init {{ set chosen = 0 }}\nscene label start\nset chosen = __rvn_enum_value_v1(\"{A}\",\"{M}\")\n\"Ready\"\nreturn\n")).unwrap()}
fn make_engine(program:rvn_parser::ParsedProgram,resources:EnumAssets1025)->Engine<crate::TerminalRenderer>{Engine::from_program_with_enum_assets1025(program,resources,Default::default(),crate::TerminalRenderer,8,HashMap::new(),Default::default()).unwrap()}
fn hot(program:&rvn_parser::ParsedProgram)->Engine<crate::TerminalRenderer>{let mut engine=make_engine(program.clone(),resources(&asset()));engine.enter_label("start").unwrap();engine.step_until_interaction().unwrap();assert!(matches!(engine.state.vars.get("chosen"),Some(Value::Enum(_))));engine}
#[test] fn enum_engine1025_real_source_constructor_executes_after_owned_startup(){let program=program();let engine=hot(&program);let value=asset().value(EnumMemberId::parse(M).unwrap()).unwrap();assert_eq!(engine.state.vars.get("chosen"),Some(&Value::Enum(value)));}
#[test] fn enum_engine1025_missing_admission_rejects_actual_execution(){let program=program();let error=match Engine::from_program_with_enum_assets1025(program,Default::default(),Default::default(),crate::TerminalRenderer,8,HashMap::new(),Default::default()){Err(error)=>error,Ok(_)=>panic!("missing literal Enum admission reached an executable Engine")};assert!(error.to_string().contains("Literal Enum reference refused before Init"),"{error}");}
#[test] fn enum_engine1025_checkpoint16_roundtrip_same_id_after_display_rename(){let program=program();let engine=hot(&program);let save=engine.capture_save15(&program,None,1,"Nominal".into()).unwrap();assert_eq!(save.format_version,16);let wire=save.encode().unwrap();assert!(wire.contains(A)&&wire.contains(M));let renamed=asset().prepare(EnumCommand::RenameMember{member:EnumMemberId::parse(M).unwrap(),display_name:"Renamed".into()}).unwrap().after().clone();let mut cold=make_engine(program.clone(),resources(&renamed));cold.restore_save15(&program,crate::save::consumer_checkpoint::Save15::decode(&wire).unwrap()).unwrap();assert_eq!(cold.state.vars.get("chosen"),engine.state.vars.get("chosen"));}
#[test] fn enum_engine1025_checkpoint15_is_preserved_without_enum_and_cannot_downgrade16(){let program=program();let cold=make_engine(program.clone(),resources(&asset()));let save=cold.capture_save15(&program,None,1,"Before nominal value".into()).unwrap();assert_eq!(save.format_version,15);let wire=save.encode().unwrap();assert!(!wire.contains("enum_references1025"));let mut restored=make_engine(program.clone(),resources(&asset()));restored.restore_save15(&program,crate::save::consumer_checkpoint::Save15::decode(&wire).unwrap()).unwrap();assert_eq!(restored.state.vars,cold.state.vars);let hot=hot(&program);let mut forged=hot.capture_save15(&program,None,1,"Nominal".into()).unwrap();forged.format_version=15;assert!(forged.encode().is_err());assert_eq!(crate::save::MAX_SUPPORTED_SAVE_FORMAT_VERSION,14);}
#[test] fn enum_engine1025_checkpoint16_missing_member_refuses_without_mutating_cold_owner(){let program=rvn_parser::parse_program(&format!("init {{ set chosen = 0\nset owner = \"{A}\"\nset member = \"{M}\" }}\nscene label start\nset chosen = __rvn_enum_value_v1(owner,member)\n\"Ready\"\nreturn\n")).unwrap();let hot=hot(&program);let save=hot.capture_save15(&program,None,1,"Nominal".into()).unwrap();let empty=asset().prepare(EnumCommand::Remove(EnumMemberId::parse(M).unwrap())).unwrap().after().clone();let mut cold=make_engine(program.clone(),resources(&empty));let before=serde_json::to_vec(&cold.state).unwrap();let error=match cold.restore_save15(&program,save){Err(error)=>error,Ok(_)=>panic!("removed Enum member was admitted")};assert!(error.to_string().contains("absent or retired"),"{error}");assert_eq!(serde_json::to_vec(&cold.state).unwrap(),before);}
#[test] fn enum_engine1025_checkpoint16_inventory_tamper_refuses_before_restore(){let program=program();let hot=hot(&program);let mut save=hot.capture_save15(&program,None,1,"Nominal".into()).unwrap();save.enum_references1025.as_mut().unwrap().clear();assert!(save.encode().is_err());}

#[test] fn enum_engine1025_actual_owned_init_continuation_has_resources_before_first_gather(){let source=format!("init {{ set chosen = __rvn_enum_value_v1(\"{A}\",\"{M}\") }}\nscene label start\n\"Ready\"\nreturn\n");let program=rvn_parser::parse_program(&source).unwrap();let engine=make_engine(program,resources(&asset()));assert_eq!(engine.state.vars.get("chosen"),Some(&Value::Enum(asset().value(EnumMemberId::parse(M).unwrap()).unwrap())));}
